      <div><label for="h-r">Roof covering</label><select id="h-r" name="roof"><option value="1" data-name="3-tab asphalt shingles">3-tab asphalt shingles</option><option value="1.25" data-name="Laminated (architectural) shingles" selected>Laminated (architectural) shingles</option><option value="1.75" data-name="Class 4 impact-resistant shingles">Class 4 impact-resistant shingles</option><option value="1.25" data-name="Concrete or clay tile">Concrete or clay tile</option><option value="1.5" data-name="Wood shakes">Wood shakes</option><option value="1.5" data-name="Slate">Slate</option><option value="1.75" data-name="Standing-seam metal (functional)">Standing-seam metal (functional)</option><option value="1" data-name="Metal panels (cosmetic dents)">Metal panels (cosmetic dents)</option></select></div>
